/**
 * @description Data-free tests (no DML, no records, no callouts) for the outbound request, reply mapping, clean-up
 * date maths, Monitor period and sharing names.
 */
@IsTest
private class IntegrationHubUnitTest {

    private static User me() {
        return new User(Id = UserInfo.getUserId());
    }

    private static IntegrationHubCallout.RequestSpec spec() {
        IntegrationHubCallout.RequestSpec s = new IntegrationHubCallout.RequestSpec();
        s.namedCredential = 'Middleware';
        s.path = '/orders/{recordId}?txn={transactionId}';
        s.method = 'PUT';
        s.timeoutMs = 15000;
        s.headersJson = '{"X-Api-Version":"2","Content-Type":"application/vnd.test+json"}';
        s.correlationId = 'corr-1';
        s.recordId = 'REC-1';
        s.transactionId = 'TXN-1';
        s.body = '{"a":1}';
        return s;
    }

    @IsTest
    static void requestUsesNamedCredentialPathAndHeaders() {
        System.runAs(me()) {
            HttpRequest req = IntegrationHubCallout.buildRequest(spec());
            Assert.areEqual('callout:Middleware/orders/REC-1?txn=TXN-1', req.getEndpoint(),
                'endpoint is the Named Credential plus the filled path');
            Assert.areEqual('PUT', req.getMethod(), 'the event method is used');
            Assert.areEqual('corr-1', req.getHeader('X-Correlation-Id'), 'the correlation Id is sent');
            Assert.areEqual('2', req.getHeader('X-Api-Version'), 'connection headers are added');
            Assert.areEqual('application/vnd.test+json', req.getHeader('Content-Type'), 'connection headers win over defaults');
            Assert.areEqual('{"a":1}', req.getBody(), 'the body is sent');
        }
    }

    @IsTest
    static void requestDefaults() {
        System.runAs(me()) {
            IntegrationHubCallout.RequestSpec s = spec();
            s.path = null;
            s.method = ' ';
            s.headersJson = null;
            s.body = null;
            HttpRequest req = IntegrationHubCallout.buildRequest(s);
            Assert.areEqual('callout:Middleware', req.getEndpoint(), 'no path gives the Named Credential alone');
            Assert.areEqual('POST', req.getMethod(), 'a blank method is POST');
            Assert.areEqual('application/json', req.getHeader('Content-Type'), 'JSON is the default content type');
            Assert.areEqual('', req.getBody(), 'no body sends an empty body');
        }
    }

    @IsTest
    static void headerJsonMustBeAnObject() {
        System.runAs(me()) {
            Assert.isTrue(IntegrationHubCallout.validHeaders(null), 'no headers are fine');
            Assert.isTrue(IntegrationHubCallout.validHeaders('{"a":"b"}'), 'an object is fine');
            Assert.isFalse(IntegrationHubCallout.validHeaders('["a"]'), 'an array is refused');
            Assert.isFalse(IntegrationHubCallout.validHeaders('{bad json'), 'invalid JSON is refused');
            Assert.isNull(IntegrationHubCallout.parseObject('{bad json'), 'invalid JSON parses to null');
        }
    }

    @IsTest
    static void statusCodeOutcome() {
        System.runAs(me()) {
            for (Integer code : new List<Integer>{ 200, 201, 204, 299 }) {
                Assert.areEqual(IntegrationHubCallout.OUTCOME_OK, IntegrationHubCallout.outcomeFor(code), code + ' is ok');
            }
            for (Integer code : new List<Integer>{ 408, 429, 500, 502, 503, 599 }) {
                Assert.areEqual(IntegrationHubCallout.OUTCOME_TEMPORARY, IntegrationHubCallout.outcomeFor(code), code + ' is temporary');
            }
            for (Integer code : new List<Integer>{ 100, 199, 300, 301, 400, 401, 403, 404, 409, 422 }) {
                Assert.areEqual(IntegrationHubCallout.OUTCOME_PERMANENT, IntegrationHubCallout.outcomeFor(code), code + ' is permanent');
            }
            Assert.areEqual(IntegrationHub.STATUS_SENT, IntegrationHubCallout.successStatus(new IH_Event__c(Expects_Callback__c = true)),
                'a 2xx waits for the callback');
            Assert.areEqual(IntegrationHub.STATUS_SUCCESS, IntegrationHubCallout.successStatus(new IH_Event__c(Expects_Callback__c = false)),
                'a 2xx without callback is Success');
            Assert.areEqual(IntegrationHub.STATUS_SUCCESS, IntegrationHubCallout.successStatus(null), 'no event is Success');
        }
    }

    @IsTest
    static void referenceFromReply() {
        System.runAs(me()) {
            Assert.areEqual('R-1', IntegrationHubCallout.reference('{"reference":"R-1","id":"X"}', 'old'), 'reference comes first');
            Assert.areEqual('42', IntegrationHubCallout.reference('{"id":42}', 'old'), 'id is used when there is no reference');
            Assert.areEqual('old', IntegrationHubCallout.reference('{"other":1}', 'old'), 'no reference keeps the current one');
            Assert.areEqual('old', IntegrationHubCallout.reference('not json', 'old'), 'invalid JSON keeps the current one');
            Assert.areEqual('old', IntegrationHubCallout.reference('[1]', 'old'), 'an array keeps the current one');
            Assert.isNull(IntegrationHubCallout.reference(null, null), 'no body and no reference is null');
            Assert.areEqual(255, IntegrationHubCallout.reference('{"id":"' + 'x'.repeat(300) + '"}', null).length(), 'long ids are clipped');
        }
    }

    @IsTest
    static void retentionAndCallbackCutoffs() {
        System.runAs(me()) {
            Datetime now = Datetime.newInstanceGmt(2026, 6, 15, 12, 0, 0);
            Assert.isNull(IntegrationHubMaintenance.retentionCutoff(null, now), 'no retention keeps everything');
            Assert.areEqual(now.addDays(-30), IntegrationHubMaintenance.retentionCutoff(30, now), 'the event retention is used');
            Assert.areEqual(now.addHours(-24), IntegrationHubMaintenance.callbackCutoff(null, now), 'default callback timeout is 24 hours');
            Assert.areEqual(now.addHours(-2), IntegrationHubMaintenance.callbackCutoff(2, now), 'the event timeout is used');
            Assert.areEqual(new List<String>{ 'Failed', 'Abandoned' }, IntegrationHubMaintenance.badStatuses(), 'retry applies to failures');
        }
    }

    @IsTest
    static void monitorPeriodAndFilter() {
        System.runAs(me()) {
            Date day = Date.newInstance(2026, 3, 10);
            Map<String, Object> period = IntegrationHubMonitorController.periodBinds(day, day);
            Assert.areEqual(Datetime.newInstance(day, Time.newInstance(0, 0, 0, 0)), period.get('fromDt'), 'from is the start of the day');
            Assert.areEqual(Datetime.newInstance(day.addDays(1), Time.newInstance(0, 0, 0, 0)), period.get('toDt'), 'the last day is included');
            Map<String, Object> open = IntegrationHubMonitorController.periodBinds(null, null);
            Assert.isTrue(((Datetime) open.get('fromDt')).year() <= 2000, 'no from date is all time');
            Assert.isTrue((Datetime) open.get('toDt') > System.now(), 'no to date runs to now');
            IntegrationHubMonitorController.GroupRequest req = new IntegrationHubMonitorController.GroupRequest();
            req.eventName = 'EV';
            Map<String, Object> binds = IntegrationHubMonitorController.groupBinds(req);
            Assert.areEqual(IntegrationHub.OUTBOUND, binds.get('dir'), 'only outbound transactions are retried');
            Assert.areEqual('EV', binds.get('eventName'), 'the group event is bound');
            Assert.isTrue(binds.containsKey('errorSummary') && binds.get('errorSummary') == null, 'a null summary is bound');
            Assert.areEqual(IntegrationHubMaintenance.badStatuses(), binds.get('bad'), 'failed and abandoned are bound');
        }
    }

    @IsTest
    static void shareObjectNames() {
        System.runAs(me()) {
            Assert.areEqual('Order__Share', IntegrationHubSharing.shareObjectName('Order__c'), 'custom share object');
            Assert.areEqual('ParentId', IntegrationHubSharing.shareParentField('Order__c'), 'custom parent field');
            Assert.areEqual('AccountShare', IntegrationHubSharing.shareObjectName('Account'), 'standard share object');
            Assert.areEqual('AccountId', IntegrationHubSharing.shareParentField('Account'), 'standard parent field');
        }
    }
}
